/* Solar Dusk Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="solar-dusk-light"] {
  --background: #fffbf4;
  --foreground: #4d3b32;
  --card: #f9f4ee;
  --card-foreground: #4d3b32;
  --popover: #f9f4ee;
  --popover-foreground: #4d3b32;
  --primary: #b75301;
  --primary-foreground: #ffffff;
  --secondary: #e7c08d;
  --secondary-foreground: #56524d;
  --muted: #f2eadd;
  --muted-foreground: #76706c;
  --accent: #f2daba;
  --accent-foreground: #56524d;
  --destructive: #971b1b;
  --destructive-foreground: #ffffff;
  --border: #e5dabd;
  --input: #e5dabd;
  --ring: #b75301;
  --chart-1: #b75301;
  --chart-2: #76706c;
  --chart-3: #a06106;
  --chart-4: #76706c;
  --chart-5: #c98a0e;
  --radius: 0.3rem;
  --sidebar: #f2eadd;
  --sidebar-foreground: #4d3b32;
  --sidebar-primary: #b75301;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #a06106;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #e5dabd;
  --sidebar-ring: #b75301;
  --font-sans: Oxanium, sans-serif;
  --font-serif: Merriweather, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: #4b3f34;
  --shadow-opacity: 0.18;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 3px 0px hsl(28 18% 25% / 0.09);
  --shadow-xs: 0px 2px 3px 0px hsl(28 18% 25% / 0.09);
  --shadow-sm:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 1px 2px -1px hsl(28 18% 25% / 0.18);
  --shadow:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 1px 2px -1px hsl(28 18% 25% / 0.18);
  --shadow-md:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 2px 4px -1px hsl(28 18% 25% / 0.18);
  --shadow-lg:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 4px 6px -1px hsl(28 18% 25% / 0.18);
  --shadow-xl:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 8px 10px -1px hsl(28 18% 25% / 0.18);
  --shadow-2xl: 0px 2px 3px 0px hsl(28 18% 25% / 0.45);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="solar-dusk-dark"] {
  --background: #1e1916;
  --foreground: #f5f5f5;
  --card: #2b2523;
  --card-foreground: #f5f5f5;
  --popover: #2b2523;
  --popover-foreground: #f5f5f5;
  --primary: #f97007;
  --primary-foreground: #ffffff;
  --secondary: #56524d;
  --secondary-foreground: #e4e4e4;
  --muted: #2b2523;
  --muted-foreground: #aaa39f;
  --accent: #1e4252;
  --accent-foreground: #e4e4e4;
  --destructive: #df2224;
  --destructive-foreground: #ffffff;
  --border: #433f3a;
  --input: #433f3a;
  --ring: #f97007;
  --chart-1: #f97007;
  --chart-2: #00a4e8;
  --chart-3: #ebb517;
  --chart-4: #aaa39f;
  --chart-5: #76706c;
  --radius: 0.3rem;
  --sidebar: #2b2523;
  --sidebar-foreground: #f5f5f5;
  --sidebar-primary: #f97007;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #00a4e8;
  --sidebar-accent-foreground: #0d294a;
  --sidebar-border: #433f3a;
  --sidebar-ring: #f97007;
  --font-sans: Oxanium, sans-serif;
  --font-serif: Merriweather, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: #0d0d0d;
  --shadow-opacity: 0.18;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 3px 0px hsl(0 0% 5% / 0.09);
  --shadow-xs: 0px 2px 3px 0px hsl(0 0% 5% / 0.09);
  --shadow-sm:
    0px 2px 3px 0px hsl(0 0% 5% / 0.18), 0px 1px 2px -1px hsl(0 0% 5% / 0.18);
  --shadow:
    0px 2px 3px 0px hsl(0 0% 5% / 0.18), 0px 1px 2px -1px hsl(0 0% 5% / 0.18);
  --shadow-md:
    0px 2px 3px 0px hsl(0 0% 5% / 0.18), 0px 2px 4px -1px hsl(0 0% 5% / 0.18);
  --shadow-lg:
    0px 2px 3px 0px hsl(0 0% 5% / 0.18), 0px 4px 6px -1px hsl(0 0% 5% / 0.18);
  --shadow-xl:
    0px 2px 3px 0px hsl(0 0% 5% / 0.18), 0px 8px 10px -1px hsl(0 0% 5% / 0.18);
  --shadow-2xl: 0px 2px 3px 0px hsl(0 0% 5% / 0.45);
}
